from django.contrib.contenttypes.models import ContentType
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from rest_framework.exceptions import PermissionDenied
from .models import GenericTagAssignment, Tag

class AddGenericTagView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        app_label = request.data.get('app_label')
        model_name = request.data.get('model')
        object_id = request.data.get('object_id')
        tag_id = request.data.get('tag_id')

        try:
            ct = ContentType.objects.get(app_label=app_label, model=model_name)
            target_instance = ct.get_object_for_this_type(pk=object_id)
            tag = Tag.objects.get(id=tag_id, organization=request.user.organization)
        except Exception:
            return Response({'error': 'Target object or Tag not found'}, status=status.HTTP_404_NOT_FOUND)

        if hasattr(target_instance, 'organization') and target_instance.organization != request.user.organization:
            raise PermissionDenied("You cannot tag resources belonging to another organization.")

        assignment, created = GenericTagAssignment.objects.get_or_create(
            content_type=ct,
            object_id=object_id,
            tag=tag,
            defaults={'assigned_by': request.user}
        )
        return Response({'status': 'tagged', 'id': assignment.id, 'tag': tag.name})
